function I(k){return'<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[k]||icons.file)+'</svg>'}
function statusBadge(s){const map={'borrador':['Borrador','gray'],'enviada':['Enviada','blue'],'recibida':['Recibida','gold'],'cotizada':['Cotizada','green'],'muestras':['En muestras','gold'],'en pedido':['Con pedido','blue'],'solicitada':['Solicitada','gold'],'confirmada':['Confirmada','green'],'en producción':['En producción','blue'],'en tránsito':['En tránsito','blue'],'recibida muestra':['Recibida','green'],'aprobada':['Aprobada','green'],'rechazada':['Rechazada','red'],'emitido':['Emitido','blue'],'aceptado':['Aceptado','green'],'entrega parcial':['Entrega parcial','gold'],'entregado':['Entregado','green'],'cerrado':['Cerrado','green']};let x=map[s]||[s||'Pendiente','gray'];return'<span class="pill '+x[1]+'">'+esc(x[0])+'</span>'}
function F(label,key,value,type='text',extra=''){return'<div class="field"><label>'+label+'</label><input '+extra+' type="'+type+'" data-rfq-key="'+key+'" value="'+esc(value??'')+'"></div>'}
function S(label, key, val, arr, target='rfq',attr=''){return'<div class="field"><label>'+label+'</label><select '+attr+' data-'+target+'-key="'+key+'"><option value="">Seleccionar</option>'+arr.map(x=>'<option value="'+esc(x)+'" '+(x===val?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></div>'}
