function txt(s){return esc(s||'—')}
function notification(t){let node=$('#toast');if(!node)return;node.textContent=t;node.classList.add('show');clearTimeout(node._tid);node._tid=setTimeout(()=>node.classList.remove('show'),3300)}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,230)}
function openDB(){return new Promise(resolve=>{if(!window.indexedDB){resolve(null);return}let req;try{req=indexedDB.open('AGORA_COMPRAS_LOCAL',1)}catch(err){resolve(null);return}req.onupgradeneeded=()=>req.result.createObjectStore('app');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)})}
async function load(){db=await openDB();if(db){try{let payload=await new Promise((res,rej)=>{let req=db.transaction('app','readonly').objectStore('app').get('data');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});if(payload&&payload.app==='agora-compras-v1')data=payload}catch(e){console.warn('BD local',e)}}else{try{let old=localStorage.getItem('AGORA_COMPRAS_LOCAL');if(old)data=JSON.parse(old)}catch{}}data.catalog=data.catalog||structuredClone(defaults);data.log=data.log||[];data.agency=data.agency||{name:'Dejavú Marketing',email:'',phone:'',defaultIva:false};['rfqs','orders','samples','suppliers'].forEach(k=>data[k]=data[k]||[])}
function save(){if(db){try{let tx=db.transaction('app','readwrite');tx.objectStore('app').put(data,'data');tx.onerror=()=>notification('No se pudo guardar. Descarga un respaldo.')}catch(e){notification('Almacenamiento lleno. Exporta una copia.')}}else{try{localStorage.setItem('AGORA_COMPRAS_LOCAL',JSON.stringify(data))}catch{notification('Almacenamiento lleno. Exporta una copia.')}}window.dispatchEvent(new CustomEvent('agora:local-saved'))}
function log(type,ref,text){data.log.unshift({id:uid('EV'),type,ref,text,at:now()});if(data.log.length>700)data.log.length=700;scheduleSave()}
const getRFQ=()=>data.rfqs.find(x=>x.id===current),getSample=()=>data.samples.find(x=>x.id===current),getOrder=()=>data.orders.find(x=>x.id===current);
const supplier=id=>data.suppliers.find(x=>x.id===id)||null;
function createRFQ(){let r={id:uid('RFQ'),folio:'PRE-'+new Date().getFullYear()+'-'+String(data.rfqs.length+1).padStart(4,'0'),title:'Nueva solicitud de presupuesto',project:'',projectId:'',supplierId:'',contact:'',dueDate:'',deliveryPlace:'',instructions:'Solicitamos su propuesta según las especificaciones de cada producto. Indique cantidades mínimas y costos unitarios de menudeo y mayoreo, así como costo de muestra.',status:'borrador',created:now(),modified:now(),receivedAt:null,items:[]};r.items.push(newItem());data.rfqs.unshift(r);current=r.id;route='solicitudes';tab='editar';log('rfq',r.id,'Solicitud creada');render()}
function newItem(){return{id:uid('IT'),product:'Hoodie',color:'',application:'',dimensions:'',extra:'',description:'Hoodie. Especificaciones por confirmar.',image:'',retailCost:'',wholesaleCost:'',minRetail:'',minWholesale:'',sampleCost:'',availability:'',comment:''}}
function generateDescription(item){const product=(item.product||'Producto').trim(),color=(item.color||'').trim(),application=(item.application||item.brand&&item.brand!=='Sin logotipo'?item.application||item.brand:'').trim(),dimensions=(item.dimensions||'').trim(),extra=(item.extra||'').trim();let text=product+(color?' en color '+color.toLowerCase():'');if(application)text+=', con '+application.charAt(0).toLowerCase()+application.slice(1);if(dimensions)text+=', '+(/^(aprox|medidas)/i.test(dimensions)?dimensions:'medidas aproximadas '+dimensions);if(extra)text+=', '+extra;return text.replace(/\.+$/,'')+'.'}
function createSupplier(name,email,phone,contact){let s={id:uid('PROV'),name:name.trim(),email:email.trim(),phone:phone.trim(),contact:contact.trim(),address:'',notes:'',created:now()};data.suppliers.push(s);log('supplier',s.id,'Proveedor agregado: '+s.name);return s}
function createSample(r){if(!r)return;if(!['cotizada','muestras','en pedido'].includes(r.status)){notification('Primero incorpora la cotización respondida del proveedor para solicitar muestras.');return}let s={id:uid('MUE'),folio:'MUE-'+new Date().getFullYear()+'-'+String(data.samples.length+1).padStart(4,'0'),rfqId:r.id,quoteFolio:r.folio,title:r.title,project:r.project,supplierId:r.supplierId,status:'solicitada',created:now(),dueDate:r.dueDate||'',deliveryPlace:r.deliveryPlace||'',instructions:'Confirma preparación y entrega de las muestras seleccionadas. Referencia: '+r.folio+'.',references:{driveUrl:'',instructions:'',sampleImages:[],driveImages:[]},comments:'',productionDays:'',deliveryDays:'',method:'',tracking:'',items:r.items.map(x=>({id:uid('MSI'),sourceId:x.id,name:x.product,description:x.description,image:x.image,qty:1,unitCost:x.sampleCost||0,confirmedQty:null,confirmedCost:null})),confirmedAt:null,acknowledgedAt:null,receivedAt:null,approvedAt:null};data.samples.unshift(s);r.status='muestras';log('sample',s.id,'Solicitud de muestras creada desde '+r.folio);current=s.id;route='muestras';tab='detalle';render()}
function createOrder(r){if(!r)return;let o={id:uid('PED'),folio:'PED-'+new Date().getFullYear()+'-'+String(data.orders.length+1).padStart(4,'0'),rfqId:r.id,title:r.title,project:r.project,projectId:r.projectId,supplierId:r.supplierId,status:'borrador',created:now(),dueDate:r.dueDate||'',deliveryPlace:r.deliveryPlace||'',notes:'Pedido generado con base en cotización '+r.folio,method:'',productionDays:'',deliveryDays:'',vat:!!data.agency.defaultIva,shipping:0,discount:0,items:r.items.map(x=>({id:uid('OI'),sourceId:x.id,name:x.product,description:x.description,image:x.image,priceType:x.wholesaleCost?'mayoreo':'menudeo',qty:n(x.wholesaleCost&&x.minWholesale?x.minWholesale:x.minRetail)||1,retailCost:n(x.retailCost),wholesaleCost:n(x.wholesaleCost),minRetail:n(x.minRetail),minWholesale:n(x.minWholesale)})),deliveries:[],acceptedAt:null};data.orders.unshift(o);r.status='en pedido';log('order',o.id,'Pedido creado desde '+r.folio);current=o.id;route='pedidos';tab='detalle';render()}
function quoteTotal(r){return sum(r.items.map(x=>n(x.wholesaleCost)*n(x.minWholesale)))+sum(r.items.map(x=>n(x.retailCost)*n(x.minRetail)))}
function orderUnit(x){return x.priceType==='mayoreo'?n(x.wholesaleCost):n(x.retailCost)}
function orderCalc(o){const subtotal=sum(o.items.map(x=>n(x.qty)*orderUnit(x)));const base=subtotal+n(o.shipping)-n(o.discount);return{subtotal,iva:o.vat?base*.16:0,total:base+(o.vat?base*.16:0)}}
function delivered(o,item){return sum(o.deliveries.map(d=>n((d.items||{})[item.id])))}
function routeTo(name,id,view){route=name;current=id||'';tab=view||(name==='solicitudes'&&id?'informacion':'detalle');filter='';query='';modal='';mobile=false;render();window.scrollTo({top:0,behavior:'instant'})}
function nav(){const navItems=[['inicio','grid','Inicio'],['solicitudes','file','Presupuestos'],['muestras','flask','Muestras'],['pedidos','package','Pedidos'],['proveedores','users','Proveedores'],['catalogo','list','Catálogo'],['respaldo','backup','Respaldo y ajustes']];return'<aside class="side '+(mobile?'open':'')+'"><div class="brand"><img class="brand-official" src="data:image/webp;base64," alt="Operaciones Agencia · Ágora by Dejavú Marketing"><div class="brand-module">COMPRAS &amp; PRODUCCIÓN</div></div><div class="side-rule"></div><div class="side-label">Espacio de trabajo</div><nav class="nav">'+navItems.map(([id,ico,label])=>'<button class="'+(id===route?'active':'')+'" data-nav="'+id+'">'+I(ico)+esc(label)+(id==='solicitudes'&&data.rfqs.filter(x=>x.status==='enviada').length?'<span class="count">'+data.rfqs.filter(x=>x.status==='enviada').length+'</span>':'')+'</button>').join('')+'</nav><div class="side-bottom"><strong>COMPRAS & PRODUCCIÓN</strong>Versión local · Datos en este dispositivo<br>Respalda periódicamente tu información.<div class="mt12" style="color:#d0a964">● Sin conexión a servidor</div></div></aside>'}
function shell(content){$('#app').innerHTML='<div class="shell '+(sidebarCollapsed?'agora-side-hidden':'')+'"><div class="mobile-shade '+(mobile?'open':'')+'" data-action="closemobile"></div>'+nav()+'<main class="main"><header class="topbar"><div class="gap12"><button class="iconbtn hamburger" data-action="menu" title="Mostrar u ocultar menú lateral" aria-label="Mostrar u ocultar menú">'+I('menu')+'</button><div class="crumb"><span class="app-name">OPERACIONES AGENCIA</span><span class="sep">/</span><strong>'+esc(paths[route]||'Compras')+'</strong></div></div><div class="topright"><div class="agora-top-actions"><button class="agora-top-action" data-action="openinvites" title="Consultar formularios y respuestas">✉ <span>Envíos</span></button><button class="agora-top-action" data-action="opennotifications" title="Notificaciones de proveedores">🔔 <span>Avisos</span></button><button class="agora-top-action" data-action="opencloud" title="Acceso y sincronización Firebase">☁ <span>Nube</span></button></div><span id="agora-storage-label" class="muted small agora-local-mark">'+esc(window.AGORA_CLOUD_STATUS?.label||'Conectando con Firebase')+'</span><span id="agora-storage-badge" class="pill" data-cloud-state="'+esc(window.AGORA_CLOUD_STATUS?.status||'pending')+'">'+(window.AGORA_CLOUD_STATUS?.mode==='cloud'?'● Nube':window.AGORA_CLOUD_STATUS?.mode==='consulta'?'● Consulta':window.AGORA_CLOUD_STATUS?.mode==='offline'?'● Offline':'● Pendiente')+'</span><div class="avatar">DV</div></div></header><div class="content">'+content+'</div></main></div><div id="modalMount"></div>';if(modal)drawModal()}
function heading(title,desc,buttons=''){return'<div class="page-title"><div><div class="caps" style="color:#aa8547;margin-bottom:7px">ÁGORA / COMPRAS</div><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div><div class="page-actions">'+buttons+'</div></div>'}
