function tableEmpty(title,description,act,label){return'<div class="empty"><div class="empty-icon">'+I('file')+'</div><h3>'+esc(title)+'</h3><p>'+esc(description)+'</p>'+(act?'<button class="btn primary" data-action="'+act+'">'+I('plus')+' '+esc(label||'Crear nuevo')+'</button>':'')+'</div>'}
function metrics(){const open=data.rfqs.filter(x=>!['borrador','cotizada','en pedido','cancelada','cerrada'].includes(x.status)).length, samples=data.samples.filter(x=>!['aprobada','rechazada','recibida muestra'].includes(x.status)).length, orders=data.orders.filter(x=>!['entregado','cerrado'].includes(x.status)).length;return'<section class="metrics">'+[['file',data.rfqs.length,'Solicitudes creadas'],['clock',open,'Presupuestos en proceso'],['flask',samples,'Muestras pendientes'],['package',orders,'Pedidos por concluir']].map(([i,v,t])=>'<div class="metric"><div class="metric-ico">'+I(i)+'</div><div><div class="number">'+v+'</div><div class="caption">'+t+'</div></div></div>').join('')+'</section>'}
function rfqRows(rows){return'<div class="tablewrap"><table><thead><tr><th>Folio / Solicitud</th><th>Proveedor</th><th>Conceptos</th><th>Fecha</th><th>Estado</th><th></th></tr></thead><tbody>'+rows.map(x=>'<tr class="clickrow" data-open="rfq" data-id="'+x.id+'"><td><div class="idlabel">'+x.folio+'</div><div class="tabletitle">'+esc(x.title)+'</div><div class="xs muted">'+esc(x.project||'Sin campaña')+'</div></td><td>'+esc(supplier(x.supplierId)?.name||'Por seleccionar')+'</td><td>'+x.items.length+' productos</td><td>'+fmt(x.created)+'</td><td>'+statusBadge(x.status)+'</td><td>'+I('chev')+'</td></tr>').join('')+'</tbody></table></div>'}
function home(){let recent=data.rfqs.slice(0,6);return'<section class="hero"><div class="hero-content"><div class="caps">DEJAVÚ MARKETING · ECOSISTEMA ÁGORA</div><h1>Compras & Producción</h1><p>Presupuestos, proveedores, muestras, pedidos y entregas. Cada gestión en un solo expediente y con seguimiento hasta su recepción.</p><button class="btn" data-action="newrfq">'+I('plus')+' Nueva solicitud de presupuesto</button></div><div class="hero-symbol"><img src="data:image/webp;base64," alt="Emblema oficial Ágora" /></div></section>'+metrics()+'<div class="section-grid"><div class="card"><div class="cardhead"><div><h2>Solicitudes recientes</h2><p class="muted small mt4">Consulta y continúa solicitudes en cualquier etapa.</p></div><button class="btn smallbtn" data-nav="solicitudes">Ver todas '+I('arrow')+'</button></div>'+(recent.length?rfqRows(recent):tableEmpty('Tu espacio está listo','Crea la primera solicitud y agrega productos con especificaciones y fotografías.','newrfq','Nueva solicitud'))+'</div><div class="card"><div class="cardhead"><h2>Accesos rápidos</h2></div><div class="cardbody"><div class="quick"><button data-action="newrfq">'+I('file')+'<span>Nueva solicitud<small>Tabla de productos y cantidades</small></span></button><button data-action="newsupplier">'+I('users')+'<span>Nuevo proveedor<small>Datos y contacto</small></span></button><button data-nav="pedidos">'+I('package')+'<span>Pedidos<small>Recepción y entregas</small></span></button><button data-nav="respaldo">'+I('download')+'<span>Respaldo<small>Descargar y restaurar datos</small></span></button></div><div class="guide mt16"><strong>¿Cómo funciona?</strong><p class="small mt8">1. Crea una solicitud y agrega los productos.<br>2. Descarga el formulario HTML del proveedor y envíalo.<br>3. Importa su respuesta JSON.<br>4. Solicita muestras o genera el pedido.<br>5. Registra envíos, entregas y recepción.</p></div><div class="mt12 fineprint">El proveedor puede responder sin instalar esta herramienta ni iniciar sesión. La sincronización se realiza mediante archivos.</div></div></div></div>'}
function rfqList(){let rows=data.rfqs.filter(x=>(!filter||x.status===filter)&&(!query||[x.folio,x.title,x.project,supplier(x.supplierId)?.name].join(' ').toLowerCase().includes(query.toLowerCase())));return heading('Solicitudes de presupuesto','Crea solicitudes de costo menudeo y mayoreo y recibe propuestas por producto.',action('Nueva solicitud','newrfq'))+'<div class="filters"><div class="search">'+I('search')+'<input data-filter="query" placeholder="Buscar por concepto, folio, proveedor o proyecto" value="'+esc(query)+'"></div><select class="select-inline" data-filter="status"><option value="">Todos los estados</option>'+['borrador','enviada','recibida','cotizada','muestras','en pedido','cancelada','cerrada'].map(x=>'<option '+(filter===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="card">'+(rows.length?rfqRows(rows):tableEmpty('No hay solicitudes en esta vista','Crea una solicitud o cambia los filtros de búsqueda.','newrfq','Nueva solicitud'))+'</div>'}
