function infoBox(k,v){return'<div class="info"><div class="k">'+esc(k)+'</div><div class="v">'+esc(v||'—')+'</div></div>'}
function rfqPage(){let r=getRFQ();if(!r)return rfqList();const s=supplier(r.supplierId);const statuses=['borrador','enviada','recibida','cotizada','muestras','en pedido','cancelada','cerrada'];
const statusSelect='<label class="agora-status-control">Estado interno <select data-agora-status aria-label="Estado interno de la solicitud">'+statuses.map(v=>'<option value="'+esc(v)+'" '+(r.status===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';
const buttons=statusSelect+action('Historial','openhistory','clock','', 'data-id="'+esc(r.id)+'"')+action('Vista y PDF','preview','eye','')+action('Enviar enlace','sendrfq','mail','gold')+action('Formulario online','supplierfile','send','primary');return heading(r.folio+' · '+r.title,'Expediente de presupuesto · Creado '+fmt(r.created),'<button class="btn" data-nav="solicitudes">← Solicitudes</button>'+buttons)+pageTabs([['informacion','Resumen'],['editar','Productos y solicitud'],['cotizacion','Respuesta del proveedor'],['seguimiento','Seguimiento']])+ (tab==='editar'?rfqEditor(r):tab==='cotizacion'?rfqQuote(r):tab==='seguimiento'?rfqTimeline(r):rfqSummary(r,s))}
function rfqSummary(r,s){return'<div class="workflow"><span class="'+(r.status==='borrador'?'current':'')+'">1. Creación</span><span class="arrow">'+I('chev')+'</span><span class="'+(r.status==='enviada'||r.status==='recibida'?'current':'')+'">2. Envío y acuse</span><span class="arrow">'+I('chev')+'</span><span class="'+(r.status==='cotizada'?'current':'')+'">3. Cotización</span><span class="arrow">'+I('chev')+'</span><span class="'+(['muestras','en pedido'].includes(r.status)?'current':'')+'">4. Muestras / pedido</span></div><div class="card"><div class="cardhead"><h2>Información general</h2>'+statusBadge(r.status)+'</div><div class="cardbody"><div class="info-grid">'+infoBox('Campaña / Proyecto',r.project)+infoBox('ID proyecto Ágora',r.projectId)+infoBox('Proveedor asignado',s?.name)+infoBox('Correo proveedor',s?.email)+infoBox('Fecha requerida',r.dueDate)+infoBox('Entrega en',r.deliveryPlace)+'</div><div class="boxnote mt16"><strong>Instrucciones: </strong>'+esc(r.instructions||'Sin instrucciones')+'</div><div class="section-title mt22"><h3>Productos solicitados ('+r.items.length+')</h3>'+action('Editar productos','editrfq','edit','','')+'</div><div class="tablewrap"><table><thead><tr><th>Imagen</th><th>Producto / Descripción</th><th>Menudeo desde</th><th>Precio unit. menudeo</th><th>Mayoreo desde</th><th>Precio unit. mayoreo</th></tr></thead><tbody>'+r.items.map(x=>'<tr><td>'+(x.image?'<img class="thumbnail" src="'+x.image+'">':'<div class="thumbnail">'+I('image')+'</div>')+'</td><td><strong>'+esc(x.product)+'</strong><div class="xs muted" style="max-width:470px">'+esc(x.description)+'</div></td><td>'+(x.minRetail!==''&&x.minRetail!=null?esc(x.minRetail)+' pzas.':'Por definir')+'</td><td>'+(x.retailCost!==''&&x.retailCost!=null?money(x.retailCost):'Por cotizar')+'</td><td>'+(x.minWholesale!==''&&x.minWholesale!=null?esc(x.minWholesale)+' pzas.':'Por definir')+'</td><td>'+(x.wholesaleCost!==''&&x.wholesaleCost!=null?money(x.wholesaleCost):'Por cotizar')+'</td></tr>').join('')+'</tbody></table></div><div class="notice mt12">Las cantidades mínimas y los costos son propuestos por el proveedor, no por la agencia. Se importan desde su formulario de respuesta.</div><div class="spread mt22" style="flex-wrap:wrap"><div class="gap8"><button class="btn" data-action="sendrfq">'+I('mail')+' Enlace por correo</button><button class="btn" data-action="marksent">'+I('check')+' Confirmar enviada</button><button class="btn" data-action="importresponse">'+I('upload')+' Importar respuesta</button></div><div class="gap8"><button class="btn" data-action="makesample">'+I('flask')+' Solicitar muestras</button><button class="btn gold" data-action="makeorder">'+I('package')+' Crear pedido</button></div></div></div></div>'}
function itemEditor(r,x,i){const attr=k=>'data-item-id="'+x.id+'" data-item-key="'+k+'"';const select=(label,key,opts)=>'<div class="field"><label>'+label+'</label><select '+attr(key)+'>'+opt(opts,x[key])+'</select></div>';const field=(label,key,placeholder='')=>'<div class="field"><label>'+label+'</label><input '+attr(key)+' type="text" value="'+esc(x[key]||'')+'" placeholder="'+esc(placeholder)+'"></div>';return'<div class="itemcard" data-item="'+x.id+'"><div class="itemhead"><div><span class="caps" style="color:#ae8746">CONCEPTO '+(i+1)+'</span><h3>'+esc(x.product||'Producto')+'</h3></div><div class="gap8"><button class="btn smallbtn" data-action="regen" data-id="'+x.id+'">'+I('arrow')+' Generar descripción</button><button class="iconbtn" data-action="removeitem" data-id="'+x.id+'" title="Eliminar producto">'+I('trash')+'</button></div></div><div class="itemgrid simplified-grid"><label class="uploader">'+(x.image?'<img src="'+x.image+'" alt="Referencia producto">':I('image')+'<span>Adjuntar foto<br><small>JPG, PNG, WebP</small></span>')+'<input type="file" accept="image/*" data-image-id="'+x.id+'" title="Subir imagen"></label>'+select('Producto', 'product', data.catalog.products)+field('Color (texto libre)','color','Ej. rojo, negro con vivos blancos')+field('Aplicación / logotipo (texto libre)','application','Ej. logo KFC en DTF textil blanco')+field('Medidas aproximadas','dimensions','Ej. 8 × 10 cm')+field('Notas o tallas (opcional)','extra','Ej. tallas pendientes')+'</div><div class="field mt12"><label>Descripción del concepto · editable</label><textarea '+attr('description')+' rows="3" placeholder="Describe el producto para el proveedor">'+esc(x.description||'')+'</textarea></div><div class="boxnote mt12"><strong>Cantidades y costos:</strong> Dejavú solicita el presupuesto; el proveedor definirá las cantidades mínimas para menudeo y mayoreo, sus precios unitarios y el costo de muestra. Podrás consultarlos en «Respuesta del proveedor».</div></div>'}
function rfqEditor(r){return'<div class="card"><section class="form-section"><div class="section-title"><div><h3>Datos del presupuesto</h3><p>Define campaña, proveedor y fecha para esta solicitud.</p></div>'+statusBadge(r.status)+'</div><div class="formgrid">'+F('Nombre de la solicitud','title',r.title)+F('Campaña / Proyecto','project',r.project)+F('ID de proyecto Ágora (opcional)','projectId',r.projectId)+'<div class="field"><label>Proveedor</label><select data-rfq-key="supplierId"><option value="">Selecciona un proveedor…</option>'+data.suppliers.map(x=>'<option value="'+x.id+'" '+(r.supplierId===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select></div>'+F('Fecha requerida','dueDate',r.dueDate,'date')+F('Ubicación / sucursal de entrega','deliveryPlace',r.deliveryPlace)+'<div class="field span3"><label>Instrucciones para proveedor</label><textarea data-rfq-key="instructions" rows="2">'+esc(r.instructions||'')+'</textarea></div></div><div class="mt12"><button class="btn smallbtn" data-action="newsupplier">'+I('plus')+' Agregar proveedor</button></div></section><section class="form-section"><div class="section-title"><div><h3>Tabla de productos</h3><p>Selecciona el producto y escribe únicamente color, aplicación, medidas y notas necesarias. El proveedor establecerá mínimos y costos.</p></div><button class="btn" data-action="additem">'+I('plus')+' Agregar producto</button></div>'+r.items.map((x,i)=>itemEditor(r,x,i)).join('')+'</section><div class="form-footer"><span class="small muted">'+I('check')+' Cambios guardados automáticamente en este equipo</span><div class="gap8"><button class="btn" data-action="preview">'+I('eye')+' Vista previa</button><button class="btn primary" data-action="supplierfile">'+I('download')+' Generar enlace para proveedor</button></div></div></div>'}
function rfqQuote(r){const a=r.supplierResponse||{},g=a.general||{};return'<div class="card"><div class="cardhead"><div><h2>Cotización del proveedor</h2><p class="muted small mt4">El proveedor define mínimos por tipo de compra y el precio unitario correspondiente.</p></div>'+statusBadge(r.status)+'</div><div class="cardbody">'+(r.receivedAt?'<div class="status pill green">Acuse recibido: '+fmt(r.receivedAt)+' · '+esc(a.receiver||'Proveedor')+'</div>':'<div class="notice">Sin acuse importado. El proveedor debe confirmar recepción antes de completar su cotización.</div>')+'<div class="spread mt16 mb14"><h3>Precios y cantidades mínimas por concepto</h3><button class="btn" data-action="importresponse">'+I('upload')+' Importar cotización</button></div><div class="tablewrap"><table><thead><tr><th>Concepto</th><th>Menudeo desde (pzas.)</th><th>Costo unit. menudeo</th><th>Mayoreo desde (pzas.)</th><th>Costo unit. mayoreo</th><th>Costo muestra</th><th>Disponibilidad</th></tr></thead><tbody>'+r.items.map(x=>'<tr><td style="min-width:175px"><strong>'+esc(x.product)+'</strong><div class="xs muted">'+esc(x.comment||x.description?.slice(0,74))+'</div></td>'+['minRetail','retailCost','minWholesale','wholesaleCost','sampleCost'].map(k=>'<td><input style="width:125px" type="number" min="0" step="'+(k.startsWith('min')?'1':'.01')+'" data-quote-id="'+x.id+'" data-quote-key="'+k+'" value="'+esc(x[k]??'')+'" placeholder="Proveedor"></td>').join('')+'<td>'+S('', 'availability', x.availability,['Disponible','Bajo fabricación','Sin existencia','Alternativa disponible'],'quote','data-quote-id="'+x.id+'"')+'</td></tr>').join('')+'</tbody></table></div><div class="section-title mt22"><div><h3>Condiciones generales</h3></div></div><div class="formgrid"><div class="field"><label>Producción (días hábiles)</label><input data-rfq-general="productionDays" type="number" min="0" value="'+esc(g.productionDays||'')+'"></div><div class="field"><label>Entrega / tránsito (días)</label><input data-rfq-general="deliveryDays" type="number" min="0" value="'+esc(g.deliveryDays||'')+'"></div><div class="field"><label>Forma de entrega</label><select data-rfq-general="deliveryType">'+opt(['Entrega en sucursal','Entrega en domicilio','Paquetería','Recolección','Por definir'],g.deliveryType)+'</select></div><div class="field"><label>Flete aproximado MXN</label><input data-rfq-general="shippingCost" type="number" min="0" step=".01" value="'+esc(g.shippingCost||'')+'"></div><div class="field"><label>Vigencia de cotización</label><input data-rfq-general="validUntil" type="date" value="'+esc(g.validUntil||'')+'"></div><div class="field"><label>Lugar de entrega</label><input data-rfq-general="deliveryPlace" value="'+esc(g.deliveryPlace||'')+'"></div><div class="field span3"><label>Comentarios del proveedor</label><textarea data-rfq-general="notes">'+esc(g.notes||'')+'</textarea></div></div><div class="spread mt22" style="flex-wrap:wrap"><button class="btn" data-action="markquoted">'+I('check')+' Marcar como cotizada</button><div class="gap8"><button class="btn" data-action="makesample">'+I('flask')+' Crear muestra</button><button class="btn gold" data-action="makeorder">'+I('package')+' Generar pedido</button></div></div></div></div>'}
function rfqTimeline(r){let events=data.log.filter(e=>e.ref===r.id);return'<div class="section-grid"><div class="card"><div class="cardhead"><h2>Historial del expediente</h2></div><div class="cardbody"><div class="feed">'+(events.length?events.map(x=>'<div class="feed-item"><strong>'+esc(x.text)+'</strong><time>'+new Date(x.at).toLocaleString('es-MX')+'</time></div>').join(''):'Aún no hay movimientos.')+'</div></div></div><div class="card"><div class="cardhead"><h2>Documentos relacionados</h2></div><div class="cardbody"><h3>Solicitudes de muestras</h3>'+data.samples.filter(s=>s.rfqId===r.id).map(s=>'<button class="btn mt8" data-open="sample" data-id="'+s.id+'">'+s.folio+' · '+statusBadge(s.status)+'</button>').join('')+'<h3 class="mt22">Pedidos</h3>'+data.orders.filter(o=>o.rfqId===r.id).map(o=>'<button class="btn mt8" data-open="order" data-id="'+o.id+'">'+o.folio+' · '+statusBadge(o.status)+'</button>').join('')+'<div class="notice">Todas las solicitudes, órdenes y entregas mantienen el folio original para su trazabilidad.</div></div></div></div>'}
function listing(kind){let isS=kind==='muestras',all=isS?data.samples:data.orders;const shown=all.filter(x=>[x.folio,x.title,x.project,supplier(x.supplierId)?.name].join(' ').toLowerCase().includes(query.toLowerCase())&&(!filter||x.status===filter));const title=isS?'Solicitudes de muestras':'Pedidos y entregas',desc=isS?'Controla costos, aprobación, producción y recepción de muestras.':'De la orden de compra al envío, recepción parcial y entrega final.';return heading(title,desc,'<button class="btn" data-nav="solicitudes">'+I('plus')+' Crear desde presupuesto</button>')+'<div class="filters"><div class="search">'+I('search')+'<input data-filter="query" placeholder="Buscar folio, concepto o proveedor" value="'+esc(query)+'"></div><select class="select-inline" data-filter="status"><option value="">Todos los estados</option>'+(isS?['solicitada','confirmada','en producción','en tránsito','recibida muestra','aprobada','rechazada']:['borrador','emitido','aceptado','en producción','en tránsito','entrega parcial','entregado','cerrado']).map(v=>'<option '+(filter===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="card">'+(shown.length?'<div class="tablewrap"><table><thead><tr><th>Folio / concepto</th><th>Proveedor</th><th>Conceptos</th><th>Fecha</th><th>Estado</th><th></th></tr></thead><tbody>'+shown.map(x=>'<tr class="clickrow" data-open="'+(isS?'sample':'order')+'" data-id="'+x.id+'"><td><div class="idlabel">'+x.folio+'</div><div class="tabletitle">'+esc(x.title)+'</div><div class="xs muted">'+esc(x.project||'Sin proyecto')+'</div></td><td>'+esc(supplier(x.supplierId)?.name||'Por definir')+'</td><td>'+x.items.length+'</td><td>'+fmt(x.created)+'</td><td>'+statusBadge(x.status)+'</td><td>'+I('chev')+'</td></tr>').join('')+'</tbody></table></div>':tableEmpty('Todavía no hay '+(isS?'muestras':'pedidos'),'Genera una '+(isS?'muestra':'orden')+' desde cualquier solicitud de presupuesto para conservar el historial.'))+'</div>'}

function sampleRefs(s){let r=s.references||(s.references={});r.driveUrl=r.driveUrl||'';r.instructions=r.instructions||'';r.sampleImages=Array.isArray(r.sampleImages)?r.sampleImages:[];r.driveImages=Array.isArray(r.driveImages)?r.driveImages:[];return r}
function safeDrive(u){try{let x=new URL(String(u||''));return x.protocol==='https:'&&['drive.google.com','docs.google.com'].includes(x.hostname)?x.href:''}catch{return ''}}
function driveThumb(u){try{let x=new URL(safeDrive(u));let id=x.pathname.match(/\/file\/d\/([\w-]+)/)?.[1]||x.searchParams.get('id');return id&&/^[\w-]{8,}$/.test(id)?'https://drive.google.com/thumbnail?id='+encodeURIComponent(id)+'&sz=w320':''}catch{return ''}}
function sampleRefsUI(s){let r=sampleRefs(s),photo=r.sampleImages.map(x=>'<div style="width:150px"><img src="'+esc(x.data)+'" style="width:150px;height:110px;object-fit:contain" alt="Muestra"><button class="btn" data-action="sample-ref-delete" data-id="'+esc(x.id)+'">Quitar</button></div>').join(''),drive=r.driveImages.map((u,i)=>'<div style="width:150px">'+(driveThumb(u)?'<img src="'+esc(driveThumb(u))+'" style="width:150px;height:110px;object-fit:contain" alt="Drive">':'<p>Vista previa no disponible</p>')+'<a target="_blank" rel="noopener noreferrer" href="'+esc(u)+'">Ver Drive</a> <button class="btn" data-action="sample-drive-delete" data-index="'+i+'">Quitar</button></div>').join('');
return '<div class="card mt20"><div class="cardhead"><h2>Referencias e indicaciones de las muestras</h2></div><div class="cardbody"><div class="field"><label>Link de Google Drive</label><input type="url" data-sample-ref="driveUrl" placeholder="https://drive.google.com/drive/folders/..." value="'+esc(r.driveUrl)+'"></div><div class="field mt16"><label>Indicaciones de la muestra</label><textarea rows="4" data-sample-ref="instructions" placeholder="Medidas, acabados y especificaciones...">'+esc(r.instructions)+'</textarea></div><div class="section-title mt22"><h3>Imágenes de muestra</h3></div><div style="display:flex;flex-wrap:wrap;gap:12px">'+photo+'</div><div class="field mt12"><label>Adjuntar fotos de muestra (máximo 6)</label><input id="sampleReferencePhotos" type="file" multiple accept="image/png,image/jpeg,image/webp"></div><div class="section-title mt22"><h3>Imágenes del Drive</h3></div><p class="muted small">Agrega el enlace individual de cada imagen (máximo 12); debe ser accesible para el proveedor. Las carpetas no se convierten automáticamente en imágenes.</p><div class="gap8"><input type="url" id="sampleDriveImageUrl" placeholder="https://drive.google.com/file/d/.../view" style="flex:1"><button class="btn" data-action="sample-drive-add">Agregar imagen</button></div><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:12px">'+drive+'</div><p class="muted small mt16">Completa estas referencias antes de generar el enlace al proveedor.</p></div></div>'}
function sampleRefsEmail(r,cid=false,cids=null){const x=r?.references;if(!x)return '';const images=Array.isArray(x.sampleImages)?x.sampleImages:[],links=Array.isArray(x.driveImages)?x.driveImages:[],url=safeDrive(x.driveUrl),notes=String(x.instructions||'');if(!url&&!notes&&!images.length&&!links.length)return '';return '<div style="padding:17px;border-top:2px solid #b99253;font:13px Arial"><h3>Referencias e indicaciones de muestras</h3>'+(url?'<p><a href="'+esc(url)+'">Abrir carpeta de Drive</a></p>':'')+(notes?'<p style="white-space:pre-line"><b>Indicaciones:</b> '+esc(notes)+'</p>':'')+images.map((p,i)=>'<img width="125" style="width:125px;max-height:125px;object-fit:contain;margin:5px" alt="Muestra" src="'+esc(cid?'cid:'+(cids?.reference?.[i]||'muestra-'+i+'@agora'):p.data)+'">').join('')+links.map((u,i)=>'<p><a href="'+esc(u)+'">'+(driveThumb(u)?'<img src="'+esc(driveThumb(u))+'" width="110" style="width:110px;vertical-align:middle">':'')+' Imagen Drive '+(i+1)+'</a></p>').join('')+'</div>'}

function samplePage(){let s=getSample();if(!s)return listing('muestras');const r=data.rfqs.find(x=>x.id===s.rfqId);const sp=supplier(s.supplierId);const total=sum(s.items.map(x=>n(x.qty)*n(x.unitCost)));return heading(s.folio+' · '+s.title,'Muestras vinculadas a '+(r?.folio||'presupuesto'),'<button class="btn" data-nav="muestras">← Muestras</button>'+action('Vista / PDF','preview','eye','')+action('Formulario','supplierfile','download','')+action('Correo con fotos y botones','email','mail','primary'))+'<div class="card"><div class="cardhead"><div><h2>Solicitud y seguimiento de muestras</h2><p class="muted small mt4">Controla costo, cantidad, confirmación y validación de cada artículo.</p></div>'+statusBadge(s.status)+'</div><div class="cardbody"><div class="info-grid">'+infoBox('Proveedor',sp?.name)+infoBox('Presupuesto original',r?.folio)+infoBox('Proyecto',s.project)+'</div><div class="section-title mt22"><h3>Artículos solicitados</h3>'+action('Agregar producto','sampleadd','plus','','')+'</div><div class="tablewrap"><table><thead><tr><th>Muestra</th><th>Cantidad</th><th>Costo unitario</th><th>Subtotal</th><th></th></tr></thead><tbody>'+s.items.map(x=>'<tr><td style="min-width:230px"><div class="gap8">'+(x.image?'<img class="thumbnail" src="'+x.image+'">':'')+'<div><strong>'+esc(x.name)+'</strong><div class="xs muted" style="max-width:320px">'+esc(x.description)+'</div></div></div></td><td><input style="max-width:88px" type="number" min="1" data-sample-item="'+x.id+'" data-key="qty" value="'+n(x.qty)+'"></td><td><input style="max-width:110px" type="number" min="0" step=".01" data-sample-item="'+x.id+'" data-key="unitCost" value="'+n(x.unitCost)+'"></td><td>'+money(n(x.qty)*n(x.unitCost))+'</td><td><button class="iconbtn" data-action="sampledelete" data-id="'+x.id+'">'+I('trash')+'</button></td></tr>').join('')+'</tbody></table></div><div class="spread mt16"><span class="muted small">Costo estimado de muestras</span><h2>'+money(total)+'</h2></div><div class="section-title mt22"><h3>Logística y aprobación</h3></div><div class="formgrid">'+S('Estado de muestras','status',s.status,['solicitada','confirmada','en producción','en tránsito','recibida muestra','aprobada','rechazada'],'sample')+'<div class="field"><label>Fecha requerida</label><input data-sample-key="dueDate" type="date" value="'+esc(s.dueDate)+'"></div><div class="field"><label>Lugar de recepción</label><input data-sample-key="deliveryPlace" value="'+esc(s.deliveryPlace)+'"></div>'+Fsample('Días de producción','productionDays',s.productionDays,'number')+Fsample('Días de entrega','deliveryDays',s.deliveryDays,'number')+S('Método de entrega','method',s.method,['Sucursal','Domicilio','Paquetería','Recolección','Otro'],'sample')+Fsample('Guía / referencia de envío','tracking',s.tracking)+'<div class="field span3"><label>Comentarios / resultado de la muestra</label><textarea data-sample-key="comments">'+esc(s.comments)+'</textarea></div></div><div class="spread mt22" style="flex-wrap:wrap"><button class="btn" data-action="importresponse">'+I('upload')+' Importar respuesta</button><div class="gap8"><button class="btn" data-action="sampleapproved">'+I('check')+' Aprobar muestra</button><button class="btn gold" data-action="makeorderfromsample">'+I('package')+' Pasar a pedido</button></div></div></div></div>'+sampleRefsUI(s)}
function Fsample(label,key,v,type='text'){return'<div class="field"><label>'+label+'</label><input data-sample-key="'+key+'" type="'+type+'" value="'+esc(v||'')+'"></div>'}
function orderPage(){let o=getOrder();if(!o)return listing('pedidos');let r=data.rfqs.find(x=>x.id===o.rfqId),sp=supplier(o.supplierId),c=orderCalc(o),rec=sum(o.items.map(x=>delivered(o,x))),all=sum(o.items.map(x=>n(x.qty)));return heading(o.folio+' · '+o.title,'Pedido vinculado a '+(r?.folio||'presupuesto'),'<button class="btn" data-nav="pedidos">← Pedidos</button>'+action('Vista / PDF','preview','eye','')+action('Imagen PNG','image','image','')+action('Formulario','supplierfile','download','')+action('Enviar por correo','email','mail','primary'))+pageTabs([['detalle','Pedido y costos'],['entregas','Entregas y recepción'],['bitacora','Bitácora']])+(tab==='entregas'?orderDeliveries(o):tab==='bitacora'?orderLog(o):'<div class="card"><div class="cardhead"><div><h2>Orden de pedido</h2><p class="small muted mt4">Cantidad y precio por concepto; se conservan los importes cotizados.</p></div>'+statusBadge(o.status)+'</div><div class="cardbody"><div class="info-grid">'+infoBox('Proveedor',sp?.name)+infoBox('Campaña / proyecto',o.project)+infoBox('Folio de origen',r?.folio)+'</div><div class="section-title mt22"><h3>Conceptos y cantidades</h3><span class="small muted">Selecciona precio menudeo o mayoreo en cada renglón</span></div><div class="tablewrap"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Tipo precio</th><th>Precio unit.</th><th>Subtotal</th><th>Recibido</th></tr></thead><tbody>'+o.items.map(x=>'<tr><td style="min-width:180px"><div class="gap8">'+(x.image?'<img class="thumbnail" src="'+x.image+'">':'')+'<div><strong>'+esc(x.name)+'</strong><div class="xs muted" style="max-width:270px">'+esc(x.description)+'</div></div></div></td><td><input style="width:85px" type="number" min="1" value="'+n(x.qty)+'" data-order-item="'+x.id+'" data-key="qty"></td><td><select style="width:112px" data-order-item="'+x.id+'" data-key="priceType"><option value="menudeo" '+(x.priceType==='menudeo'?'selected':'')+'>Menudeo</option><option value="mayoreo" '+(x.priceType==='mayoreo'?'selected':'')+'>Mayoreo</option></select></td><td><strong>'+money(orderUnit(x))+'</strong><div class="xs muted">Men. desde '+(x.minRetail||'—')+' pzas. · May. desde '+(x.minWholesale||'—')+' pzas.</div></td><td>'+money(n(x.qty)*orderUnit(x))+'</td><td>'+delivered(o,x)+' / '+n(x.qty)+'</td></tr>').join('')+'</tbody></table></div><div class="split mt22"><div><h3>Producción y envío</h3><div class="formgrid mt12">'+S('Estado de pedido','status',o.status,['borrador','emitido','aceptado','en producción','en tránsito','entrega parcial','entregado','cerrado'],'order')+'<div class="field"><label>Entrega requerida</label><input data-order-key="dueDate" type="date" value="'+esc(o.dueDate)+'"></div><div class="field"><label>Lugar / sucursal</label><input data-order-key="deliveryPlace" value="'+esc(o.deliveryPlace)+'"></div>'+Ford('Días de producción','productionDays',o.productionDays,'number')+Ford('Días de entrega','deliveryDays',o.deliveryDays,'number')+S('Método de envío','method',o.method,['Sucursal','Domicilio','Paquetería','Recolección','Otro'],'order')+'<div class="field span3"><label>Indicaciones al proveedor</label><textarea data-order-key="notes">'+esc(o.notes||'')+'</textarea></div></div></div><div><h3>Resumen económico</h3><div class="totals mt12"><div><span>Subtotal</span><strong>'+money(c.subtotal)+'</strong></div><div><span>Flete / envío MXN</span><input style="width:105px;text-align:right" type="number" min="0" step=".01" data-order-key="shipping" value="'+n(o.shipping)+'"></div><div><span>Descuento MXN</span><input style="width:105px;text-align:right" type="number" min="0" step=".01" data-order-key="discount" value="'+n(o.discount)+'"></div><div><label class="gap8"><input type="checkbox" data-order-key="vat" '+(o.vat?'checked':'')+'> IVA (16%)</label><strong>'+money(c.iva)+'</strong></div><div class="grand"><span>TOTAL</span><span>'+money(c.total)+'</span></div></div><div class="boxnote mt16">Recepción registrada: <strong>'+rec+' de '+all+' unidades</strong>. Consulta la pestaña Entregas para controlar saldos.</div></div></div></div><div class="form-footer"><span class="small muted">'+I('check')+' Edición local y guardado automático</span><div class="gap8"><button class="btn" data-action="orderemit">'+I('check')+' Emitir pedido</button><button class="btn gold" data-tab="entregas">'+I('truck')+' Registrar entrega</button></div></div></div>')}
