function base64UTF8(s){const bytes=new TextEncoder().encode(s);let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary)}
function wrapB64(s){return s.match(/.{1,76}/g)?.join('\r\n')||''}
function buildRichEmailMime(kind,r,inviteUrls=null){
 const s=supplier(r.supplierId);
 if(!s||!s.email||!(/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(s.email)))throw new Error('Indica un correo de proveedor válido antes de crear el borrador.');
 // Each generated email has its own Content-IDs, preventing stale-image reuse between drafts.
 const nonce=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
 const mix='dvm-mix-'+nonce,alternate='dvm-alt-'+nonce,related='dvm-rel-'+nonce,CRLF='\r\n',parts=[];
 const push=(...lines)=>parts.push(lines.join(CRLF));
 const cids={logo:'marca-'+nonce+'@agora.dejavu',photos:(r.items||[]).map((_,i)=>'producto-'+(i+1)+'-'+nonce+'@agora.dejavu')};
 const imgs=[{mime:'image/png',bytes:AGORA_EMAIL_LOGO.split(',')[1],cid:cids.logo,filename:'dejavu-marketing-logo.png'}];
 (r.items||[]).forEach((x,i)=>{const im=emailImageData(x.image);if(im)imgs.push({...im,cid:cids.photos[i],filename:'producto-'+(i+1)+'.'+(im.mime==='image/png'?'png':im.mime==='image/webp'?'webp':im.mime==='image/gif'?'gif':'jpg')})});
 push('MIME-Version: 1.0','To: '+s.email,'Subject: =?UTF-8?B?'+base64UTF8(emailSubject(kind,r))+'?=','Content-Type: multipart/mixed; boundary="'+mix+'"','');
 // Widely supported MIME: mixed -> alternative -> (plain text | related(html + inline images)).
 push('--'+mix,'Content-Type: multipart/alternative; boundary="'+alternate+'"','');
 push('--'+alternate,'Content-Type: text/plain; charset="utf-8"','Content-Transfer-Encoding: base64','',wrapB64(base64UTF8(emailText(kind,r,inviteUrls))));
 push('--'+alternate,'Content-Type: multipart/related; boundary="'+related+'"; type="text/html"','');
 push('--'+related,'Content-Type: text/html; charset="utf-8"','Content-Transfer-Encoding: base64','',wrapB64(base64UTF8('<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"></head><body>'+emailMarkup(kind,r,'cid',cids,inviteUrls)+'</body></html>')));
 for(const im of imgs)push('--'+related,'Content-Type: '+im.mime+'; name="'+im.filename+'"','Content-Transfer-Encoding: base64','Content-Disposition: inline; filename="'+im.filename+'"','Content-ID: <'+im.cid+'>','X-Attachment-Id: '+im.cid,'',wrapB64(im.bytes));
 push('--'+related+'--','--'+alternate+'--');
 if(!inviteUrls){const filename='AGORA_FORMULARIO_'+r.folio+'.html';
 push('--'+mix,'Content-Type: text/html; name="'+filename+'"','Content-Transfer-Encoding: base64','Content-Disposition: attachment; filename="'+filename+'"','',wrapB64(base64UTF8(supplierHTML(kind,r))));}
 push('--'+mix+'--','');
 return parts.join(CRLF);
}
function exportRichEmail(){const d=getDoc(),r=d.record;if(!r)return;
 try{const mime=buildRichEmailMime(d.kind,r);downloadFile('AGORA_CORREO_VISUAL_'+r.folio+'.eml',mime,'message/rfc822');log(d.kind,r.id,'Correo .EML preparado (no enviado)');notification('Correo visual descargado con fotos y formulario.');}
 catch(e){notification(e.message)}
}
let gmailBusy=false,gmailDraftResult=null,gmailTokenClient=null,gmailClientConfigured='';
const GMAIL_SCOPE='https://www.googleapis.com/auth/gmail.compose';
